changeSet.sql:
CREATE UNIQUE INDEX uk_active_physical_borrow
ON borrows (user_id, book_id)
WHERE borrow_type = 'PHYSICAL' AND status IN ('REQUESTED', 'APPROVED');

CREATE UNIQUE INDEX uk_active_digital_borrow
ON borrows (user_id, book_id)
WHERE borrow_type = 'DIGITAL' AND status IN ('REQUESTED', 'APPROVED');

rollback.sql:
CREATE UNIQUE INDEX idx_borrows_one_active_per_user_book
ON borrows (user_id, book_id)
WHERE status IN ('REQUESTED', 'APPROVED');
